from typing import Iterable, List

from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from hourglass.errors import ProjectError

def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")

def _counts(shifts: List[Shift]) -> dict:
    counts = {}
    for shift in shifts:
        counts[shift.worker] = counts.get(shift.worker, 0) + 1
    return counts

def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most scheduled hours first."""
    shifts = list(shifts)
    _check(shifts)
    counts = _counts(shifts)
    mins = worker_minutes(shifts)
    order = sorted(mins, key=lambda w: (-mins[w], w))
    return [
        f"{w}: {counts[w]} shifts, {mins[w] / 60:.1f} hours"
        for w in order
    ]

