# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_one_decimal(self):
        lines = timesheet_lines([
            shift("Ann", "mon", 540, 630),
            shift("Bob", "mon", 540, 1020),
            shift("Ann", "tue", 540, 600)
        ])
        self.assertEqual(lines, [
            "Bob: 1 shifts, 8.0 hours",
            "Ann: 2 shifts, 2.5 hours"
        ])

    def test_empty_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([shift(" ", "mon", 540, 600)])
